// Get missing number from a sequence or get nex//https://dotnetfiddle.net/8FS5yLusing System;using System.IO;using System.Security.Cryptography;using System.Collections.Generic;using System.Linq;namespace Rextester{    public class Program{        public static void Main(string[] args){            Console.WriteLine(new List<int>(){0, 1,2, 3,4,5,5, 7,8}.GetUniqueNumber());        }    }	public static class MathExtensions {			public static int GetUniqueNumber(this List<int> list) {			// Sorting the int list			list.Sort();			// Last number of the list (plus one if nothing missing)			var lastNumber = list.Last() + 1;			// Range that contains all numbers in the interval [0,... lastNumber]			var range = Enumerable.Range(0, lastNumber);			// Get missing numbers in interval			var missingNumbers = range.Except(list).ToList();			// If missing found get smaller else get last(higer)			return missingNumbers.Count > 0 ? missingNumbers.First() : lastNumber;		}	}}https://ideone.com/CDOr9r// Get all before underscoreusing System;using System.Text.RegularExpressions;public class Test{	public static void Main()	{		var result = Regex.Match("000AB22CD_abc", @".+?(?=_)");		if (result.Success) 		{ 			Console.Write(result.Value);		} else {							Console.Write("not indexed");		}	}}// Get index from end of stringusing System;using System.Text.RegularExpressions;public class Test{	public static void Main()	{		var result = Regex.Match("000AB22CD_444", @"\d+$", RegexOptions.LeftToRight);		if (result.Success) 		{ 			Console.Write(result.Value);		} else {							Console.Write("not indexed");		}	}}